/* ============================================
   New Homepage Layout (post-refactor)
   ============================================ */

/* Section Shell - generic content section */
.section-shell {
    padding: 80px 20px;
    max-width: 1100px;
    margin: 0 auto;
}

/* Section lead text */
.section-lead {
    text-align: center;
    color: var(--text-light);
    font-size: 1.1rem;
    max-width: 640px;
    margin: 0 auto 50px;
    line-height: 1.7;
}

/* Choice Grid - 3 starting point cards */
.choice-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    max-width: 1100px;
    margin: 0 auto;
}

.choice-card {
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 35px 30px;
    box-shadow: var(--shadow-sm);
    transition: all 0.3s ease;
}

.choice-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
    border-color: rgba(42, 82, 152, 0.2);
}

.choice-card h3 {
    font-size: 1.2rem;
    color: var(--primary);
    margin-bottom: 12px;
    font-family: 'Inter', sans-serif;
    font-weight: 600;
}

.choice-card p {
    color: var(--text-light);
    font-size: 0.95rem;
    margin-bottom: 16px;
    line-height: 1.6;
}

.choice-card ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.choice-card ul li {
    color: var(--text);
    font-size: 0.9rem;
    padding: 6px 0;
    padding-left: 20px;
    position: relative;
}

.choice-card ul li::before {
    content: '✓';
    position: absolute;
    left: 0;
    color: var(--success);
    font-weight: bold;
}

/* Band - colored background section */
.band {
    background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
    color: white;
    padding: 80px 20px;
}

.band .section-title {
    color: white;
}

.band .section-lead {
    color: rgba(255,255,255,0.85);
}

/* Package Grid */
.package-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 30px;
    max-width: 900px;
    margin: 0 auto 40px;
}

.package-card {
    background: var(--white);
    border: 2px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 40px 35px;
    box-shadow: var(--shadow);
    text-align: center;
    transition: all 0.3s ease;
}

.package-card:hover {
    border-color: var(--primary);
    box-shadow: var(--shadow-lg);
    transform: translateY(-3px);
}

.package-card h3 {
    font-size: 1.4rem;
    color: var(--dark);
    margin-bottom: 12px;
    font-family: 'Inter', sans-serif;
}

.price-line {
    font-size: 2.2rem;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 16px;
}

.package-card p {
    color: var(--text-light);
    font-size: 0.95rem;
    line-height: 1.6;
    margin-bottom: 20px;
}

.package-card ul {
    list-style: none;
    padding: 0;
    margin: 0 0 20px 0;
    text-align: left;
}

.package-card ul li {
    color: var(--text);
    font-size: 0.9rem;
    padding: 6px 0;
    padding-left: 22px;
    position: relative;
}

.package-card ul li::before {
    content: '✓';
    position: absolute;
    left: 0;
    color: var(--success);
    font-weight: bold;
}

/* Package Actions */
.package-actions {
    display: flex;
    justify-content: center;
    gap: 20px;
    flex-wrap: wrap;
    margin-top: 10px;
}

/* Proof Grid - Why Patients Choose Us */
.proof-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 30px;
    max-width: 1100px;
    margin: 0 auto;
}

.proof-card {
    text-align: center;
    padding: 30px 20px;
}

.proof-card h3 {
    font-size: 1.15rem;
    color: var(--primary);
    margin-bottom: 12px;
    font-family: 'Inter', sans-serif;
    font-weight: 600;
}

.proof-card p {
    color: var(--text-light);
    font-size: 0.95rem;
    line-height: 1.7;
}

/* Hospital Preview Grid */
.hospital-preview {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 25px;
    max-width: 1100px;
    margin: 0 auto 40px;
}

.hospital-preview .hospital-card {
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: all 0.3s ease;
}

.hospital-preview .hospital-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.hospital-preview .hospital-card img {
    width: 100%;
    height: 160px;
    object-fit: cover;
}

.hospital-preview .hospital-card h3 {
    font-size: 1.05rem;
    padding: 16px 16px 4px;
    color: var(--dark);
}

.hospital-preview .specialty,
.hospital-preview .city,
.hospital-preview .certification {
    font-size: 0.85rem;
    padding: 2px 16px;
    color: var(--text-light);
}

/* Final Banner */
.final-banner {
    background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
    color: white;
    padding: 60px 40px;
    border-radius: var(--radius-xl);
    max-width: 1100px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
    flex-wrap: wrap;
}

.final-banner h2 {
    color: white;
    font-size: 2rem;
    margin-bottom: 10px;
}

.final-banner p {
    color: rgba(255,255,255,0.9);
    font-size: 1rem;
    max-width: 560px;
}

.final-banner .cta-button {
    background: white;
    color: var(--primary);
    padding: 14px 32px;
    border-radius: 50px;
    font-weight: 600;
    text-decoration: none;
    white-space: nowrap;
    transition: all 0.3s ease;
    flex-shrink: 0;
}

.final-banner .cta-button:hover {
    background: var(--light);
    transform: translateY(-2px);
}

/* Responsive */
@media (max-width: 900px) {
    .choice-grid,
    .proof-grid,
    .hospital-preview {
        grid-template-columns: 1fr;
    }
    .package-grid {
        grid-template-columns: 1fr;
    }
    .final-banner {
        flex-direction: column;
        text-align: center;
    }
    .final-banner p {
        max-width: 100%;
